	if eb.OperatingHistoryAttested() { return nil, nil }
	fam := practiceEvidence()
	for _, block := range blocks { for i := range fam.BannedClaims { bc := &fam.BannedClaims[i]
		for _, loc := range bc.re.FindAllStringIndex(block, -1) {
			switch { case negatedClaimMatch(block, loc[0]): record(gone, …, "negated in its own clause")
			         case hedgedPracticeMatch(block, loc[0]): record(gone, …, "hedged by a preceding conditional")
			         default: record(live, …, bc.Reason) } } } }
	// findings carry Check: "practice_claim"; suppressed carry why
}

